// Computed property pour formater la frame actuelle
// Le script original remplaçait les espaces par des espaces insécables (&nbsp;)
const currentFrame = computed(() => {
  return frames[currentIndex.value].replace(/ /g, "&nbsp;");
});

// Démarrer l'animation au montage
onMounted(() => {
  timer = setInterval(() => {
    // Incrémente l'index, et retourne à 0 si on dépasse la fin
    currentIndex.value = (currentIndex.value + 1) % frames.length;
  }, delay);
});

// Nettoyer le timer à la destruction du composant
onBeforeUnmount(() => {
  if (timer) clearInterval(timer);
});
</script>

<template>
  <div class="ascii-container">
    <div class="ascii-content" v-html="currentFrame"></div>
  </div>
</template>

<style scoped>
.ascii-container {
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #000; /* Fond noir pour le contraste ASCII habituel */
  color: #fff; /* Texte blanc */
  padding: 20px;
  border-radius: 8px;
}

.ascii-content {
  font-size: 1rem; /* size=3 équivaut à peu près à du texte standard ou légèrement plus grand */
  line-height: 1.1; /* Ajustement pour que l'ASCII ne soit pas trop étiré verticalement */
  white-space: normal; /* Important car on utilise &nbsp; et <br> */
}
</style>